"""
BizMetrics Multilingual Translation System (English, हिंदी, Hinglish)
Provides centralized, persistent translation across dashboards, sidebar,
KPI cards, forms, tables, charts, exports, customer portal, and AI Advisor.
"""
from __future__ import annotations

import functools
import re
from typing import Any, Optional
import pandas as pd
import streamlit as st

SUPPORTED_LANGUAGES = ["English", "हिंदी", "Hinglish"]
DEFAULT_LANGUAGE = "English"

__all__ = [
    "t",
    "get_current_language",
    "set_current_language",
    "translate_df",
    "translate_status",
    "render_language_selector",
    "normalize_lang",
    "TRANSLATIONS",
    "SUPPORTED_LANGUAGES",
    "DEFAULT_LANGUAGE",
]

# Regex for stripping markdown headings (#, ##, ###) and leading symbols/emojis
PREFIX_RE = re.compile(r"^(\s*#+\s*|[^\w\s\(\)\[\]\{\}\<\>\-\+\,\.\'\"\:\;\/]+\s*)+")
SUFFIX_EMOJI_RE = re.compile(r"[\s👋💡🚨📈📉🛡️🏪📱📑💧⚖️📦🧾🏷️🏭💰🛒🌟⚒️]+$")

def normalize_lang(language: Optional[str]) -> str:
    """Normalizes any incoming language string to one of the 3 supported options."""
    if not language:
        return DEFAULT_LANGUAGE
    lang_str = str(language).strip()
    if lang_str in ("हिंदी", "हिन्दी", "Hindi", "hi", "Hindi (हिंदी)"):
        return "हिंदी"
    if lang_str.lower() in ("hinglish", "en-hi"):
        return "Hinglish"
    return "English"


def translate_df(df: Any, lang: Optional[str] = None) -> Any:
    """Early resilient definition to ensure the symbol is always immediately importable."""
    if df is None:
        return df
    if not hasattr(df, "columns"):
        return df
    try:
        target_lang = normalize_lang(lang) if lang else get_current_language()
        df_copy = df.copy()
        if "t" in globals() and callable(globals().get("t")):
            new_cols = {col: globals()["t"](str(col), target_lang) for col in df_copy.columns}
            df_copy.rename(columns=new_cols, inplace=True)
        return df_copy
    except Exception:
        return df


def translate_status(val: Any, lang: Optional[str] = None) -> str:
    """Early resilient definition to ensure the symbol is always immediately importable."""
    if val is None:
        return ""
    if "t" in globals() and callable(globals().get("t")):
        return globals()["t"](str(val).strip(), lang)
    return str(val)


REPORTED_MISSING_KEYS: set[str] = set()

def get_missing_translations_report() -> list[str]:
    """Returns all unique keys that were requested in non-English mode but missing in the dictionary."""
    return sorted(list(REPORTED_MISSING_KEYS))


def get_current_language() -> str:
    """Retrieve the active language from streamlit session state with priority fallbacks."""
    if hasattr(st, "session_state"):
        # Check unified global key first, then secondary keys
        for k in (
            "global_language_dropdown",
            "language",
            "selected_language",
            "current_language",
            "customer_lang",
            "advisor_language",
            "landing_page_lang",
            "syb_language",
            "rep_lang_select",
        ):
            val = st.session_state.get(k)
            if val:
                return normalize_lang(val)
    return DEFAULT_LANGUAGE


def set_current_language(language: str) -> None:
    """Set the active language in streamlit session state across all modules and synchronize all selector keys."""
    norm = normalize_lang(language)
    if hasattr(st, "session_state"):
        st.session_state["language"] = norm
        st.session_state["selected_language"] = norm
        st.session_state["customer_lang"] = norm
        st.session_state["advisor_language"] = norm
        st.session_state["global_language_dropdown"] = norm
        st.session_state["global_lang_selector"] = norm
        st.session_state["cust_lang_toggle"] = norm
        st.session_state["advisor_lang_select"] = norm
        st.session_state["landing_page_lang"] = norm
        st.session_state["syb_language"] = norm
        st.session_state["rep_lang_select"] = norm


