# Pre-indexed lowercase maps for fast O(1) case-insensitive lookup
_LOWER_TRANSLATIONS: dict[str, dict[str, str]] = {
    lang_name: {k.lower(): v for k, v in l_map.items()}
    for lang_name, l_map in TRANSLATIONS.items()
}


@functools.lru_cache(maxsize=8192)
def _t_cached(clean_k: str, target_lang: str) -> str:
    """Core cached translation engine for normalized strings and explicit target language."""
    lang_dict = TRANSLATIONS.get(target_lang, TRANSLATIONS["English"])
    lower_dict = _LOWER_TRANSLATIONS.get(target_lang, _LOWER_TRANSLATIONS["English"])

    # 1. Direct match
    if clean_k in lang_dict:
        return lang_dict[clean_k]

    # 2. Fast O(1) case-insensitive match
    ck_lower = clean_k.lower()
    if ck_lower in lower_dict:
        return lower_dict[ck_lower]

    # 3. Smart prefix and emoji preservation
    m = PREFIX_RE.match(clean_k)
    if m:
        prefix = m.group(0)
        core = clean_k[len(prefix):].strip()
        core_lower = core.lower()

        # Check core in target dictionary
        if core in lang_dict:
            return prefix + lang_dict[core]
        if core_lower in lower_dict:
            return prefix + lower_dict[core_lower]

        # Check core with trailing emoji stripped
        core_no_suffix = SUFFIX_EMOJI_RE.sub("", core).strip()
        if core_no_suffix:
            if core_no_suffix in lang_dict:
                return prefix + lang_dict[core_no_suffix]
            cns_lower = core_no_suffix.lower()
            if cns_lower in lower_dict:
                return prefix + lower_dict[cns_lower]

        # Fallback to English dictionary for core
        if target_lang != "English":
            eng_dict = TRANSLATIONS["English"]
            eng_lower = _LOWER_TRANSLATIONS["English"]
            if core in eng_dict:
                return prefix + eng_dict[core]
            if core_lower in eng_lower:
                return prefix + eng_lower[core_lower]

    # 4. Trailing emoji strip without prefix
    no_suffix = SUFFIX_EMOJI_RE.sub("", clean_k).strip()
    if no_suffix and no_suffix != clean_k:
        suffix = clean_k[len(no_suffix):]
        if no_suffix in lang_dict:
            return lang_dict[no_suffix] + suffix
        ns_lower = no_suffix.lower()
        if ns_lower in lower_dict:
            return lower_dict[ns_lower] + suffix

    # 5. English dictionary fallback
    if target_lang != "English":
        if len(clean_k) > 1 and not clean_k.isdigit() and not clean_k.startswith("http") and not clean_k.startswith("<"):
            REPORTED_MISSING_KEYS.add(f"[{target_lang}] {clean_k}")
        eng_dict = TRANSLATIONS["English"]
        eng_lower = _LOWER_TRANSLATIONS["English"]
        if clean_k in eng_dict:
            return eng_dict[clean_k]
        if ck_lower in eng_lower:
            return eng_lower[ck_lower]

    return clean_k


def t(key: str, lang: Optional[str] = None) -> str:
    """
    Translates a given text key to the selected language (English, हिंदी, Hinglish).
    Features smart markdown header and emoji stripping to ensure 100% translation coverage.
    Falls back gracefully to English and then to the raw key.
    High-performance cached implementation.
    """
    if not key or not isinstance(key, str):
        return "" if key is None else str(key)

    target_lang = normalize_lang(lang) if lang else get_current_language()
    clean_k = key.strip()
    return _t_cached(clean_k, target_lang)


def translate_status(val: Any, lang: Optional[str] = None) -> str:
    """Translates common transactional and operational status values."""
    if val is None:
        return ""
    s_val = str(val).strip()
    return t(s_val, lang)


def translate_df(df: pd.DataFrame, lang: Optional[str] = None) -> pd.DataFrame:
    """
    Returns a copy of a DataFrame with translated column headers
    and translated operational status values (where applicable).
    Optimized: Returns original DataFrame unchanged for English.
    """
    if df is None or df.empty:
        return df

    target_lang = normalize_lang(lang) if lang else get_current_language()
    if target_lang == "English":
        return df

    df_copy = df.copy()

    # Translate column headers
    new_cols = {col: t(str(col), target_lang) for col in df_copy.columns}
    df_copy.rename(columns=new_cols, inplace=True)

    # Translate common status values
    status_cols = [c for c in df_copy.columns if any(s in str(c).lower() for s in ("status", "priority", "payment mode", "mode", "category"))]
    for sc in status_cols:
        try:
            df_copy[sc] = df_copy[sc].apply(lambda v: t(str(v), target_lang) if pd.notna(v) and str(v).strip() in TRANSLATIONS[target_lang] else v)
        except Exception:
            pass

    return df_copy


def render_language_selector(key: str = "global_lang_selector", label_visibility: str = "collapsed") -> str:
    """
    Renders the standardized top-right language selector component.
    Options: English, हिंदी, Hinglish.
    Preserves selection in st.session_state across navigation and reruns.
    """
    current = get_current_language()
    options = ["English", "हिंदी", "Hinglish"]
    current_idx = options.index(current) if current in options else 0

    chosen = st.selectbox(
        "Language",
        options=options,
        index=current_idx,
        key=key,
        label_visibility=label_visibility,
        help="Switch language / भाषा बदलें / Bhasha chunein"
    )

    if chosen != current:
        set_current_language(chosen)
        st.rerun()

    return chosen


